INSERT INTO continental_jurisdictions (country_code,country_name,region_code,status,legal_framework_version,data_protection_notes) SELECT 'NG','Nigeria','WAF','Seeded','NG-2026-08-23','Nigeria Data Protection Act 2023 applies to personal-data processing; jurisdictional implementation requires NDPC validation.' WHERE NOT EXISTS (SELECT 1 FROM continental_jurisdictions WHERE country_code='NG');
INSERT INTO regulatory_sources (jurisdiction_id,authority_name,source_title,source_url,source_type,publication_date,effective_date,authority_verified,status) SELECT id,'Nigerian State/Federal public legal repository','Land Use Act 1978','https://www.ekitistate.gov.ng/wp-content/uploads/saber/Land-Use-Act-1978-LawGlobal-Hub.pdf','Act',NULL,'1978-03-29',false,'Discovered' FROM continental_jurisdictions WHERE country_code='NG' AND NOT EXISTS (SELECT 1 FROM regulatory_sources WHERE source_title='Land Use Act 1978');
INSERT INTO regulatory_sources (jurisdiction_id,authority_name,source_title,source_url,source_type,publication_date,effective_date,authority_verified,status) SELECT id,'Corporate Affairs Commission','Companies and Allied Matters Act 2020','https://www.cac.gov.ng/wp-content/uploads/2020/12/CAMA-NOTE-BOOK-FULL-VERSION.pdf','Act','2020-08-07','2020-01-01',true,'Discovered' FROM continental_jurisdictions WHERE country_code='NG' AND NOT EXISTS (SELECT 1 FROM regulatory_sources WHERE source_title='Companies and Allied Matters Act 2020');
INSERT INTO regulatory_sources (jurisdiction_id,authority_name,source_title,source_url,source_type,effective_date,authority_verified,status) SELECT id,'Nigeria Data Protection Commission','Nigeria Data Protection Act 2023','https://www.ndpc.gov.ng/ndp-act-2023/','Act','2023-06-12',true,'Discovered' FROM continental_jurisdictions WHERE country_code='NG' AND NOT EXISTS (SELECT 1 FROM regulatory_sources WHERE source_title='Nigeria Data Protection Act 2023');
INSERT INTO regulatory_sources (jurisdiction_id,authority_name,source_title,source_url,source_type,effective_date,authority_verified,status) SELECT id,'National Environmental Standards and Regulations Enforcement Agency','Environmental Laws and Regulations / EIA Act','https://nesrea.gov.ng/laws-regulations/','Regulatory repository',NULL,true,'Discovered' FROM continental_jurisdictions WHERE country_code='NG' AND NOT EXISTS (SELECT 1 FROM regulatory_sources WHERE source_title='Environmental Laws and Regulations / EIA Act');
INSERT INTO regulatory_sources (jurisdiction_id,authority_name,source_title,source_url,source_type,effective_date,authority_verified,status) SELECT id,'Ministry of Solid Minerals Development','Nigerian Minerals and Mining Act 2007','https://msmd.gov.ng/downloads/','Act','2007-03-16',true,'Discovered' FROM continental_jurisdictions WHERE country_code='NG' AND NOT EXISTS (SELECT 1 FROM regulatory_sources WHERE source_title='Nigerian Minerals and Mining Act 2007');
INSERT INTO regulatory_sources (jurisdiction_id,authority_name,source_title,source_url,source_type,effective_date,authority_verified,status) SELECT id,'Ministry of Solid Minerals Development','Nigerian Minerals and Mining Regulations 2011','https://msmd.gov.ng/downloads/','Regulations','2011-05-24',true,'Discovered' FROM continental_jurisdictions WHERE country_code='NG' AND NOT EXISTS (SELECT 1 FROM regulatory_sources WHERE source_title='Nigerian Minerals and Mining Regulations 2011');
INSERT INTO regulatory_sources (jurisdiction_id,authority_name,source_title,source_url,source_type,effective_date,authority_verified,status) SELECT id,'National Environmental Standards and Regulations Enforcement Agency','National Environmental Regulations repository','https://nesrea.gov.ng/laws-regulations/','Regulatory repository',NULL,true,'Discovered' FROM continental_jurisdictions WHERE country_code='NG' AND NOT EXISTS (SELECT 1 FROM regulatory_sources WHERE source_title='National Environmental Regulations repository');
INSERT INTO jurisdiction_rights_frameworks (jurisdiction_id,tenure_category,community_recognition_model,consultation_requirement,consent_requirement,traditional_authority_role,benefit_sharing_model,grievance_model,disclosure_requirement,restricted_data_rules,source_reference,status) SELECT id,'Land / occupancy','State-administered statutory and customary interests require context-specific review','Required where applicable; exact workflow must be validated by jurisdiction and project type','Do not infer consent from title or investor documentation','Context-specific; validate applicable state/customary structure','Project-specific and sector-specific; validate before activation','Formal grievance route plus applicable statutory/court processes','Role-based; personal/community-sensitive data restricted','Personal data and sensitive community spatial information restricted','Land Use Act 1978; state-level land frameworks','Draft' FROM continental_jurisdictions WHERE country_code='NG' AND NOT EXISTS (SELECT 1 FROM jurisdiction_rights_frameworks WHERE tenure_category='Land / occupancy');
INSERT INTO jurisdiction_transparency_rules (jurisdiction_id,subject_type,public_fields,restricted_fields,consent_required,rule_reason) SELECT id,'Community rights', '["community_name","case_status","aggregate_benefit_status"]'::jsonb,'["representative_identity","sensitive_geometry","personal_contact_data","protected_evidence"]'::jsonb,true,'Protect community representatives, sensitive locations and personal data while allowing governed aggregate transparency.' FROM continental_jurisdictions WHERE country_code='NG' AND NOT EXISTS (SELECT 1 FROM jurisdiction_transparency_rules WHERE subject_type='Community rights');
INSERT INTO regulatory_rules (source_id,rule_code,rule_domain,rule_text,applicability,evidence_reference) SELECT id,'NG-LAND-001','Land','Land administration and rights-of-occupancy decisions must be evaluated under the Land Use Act and applicable state-level instruments; the platform must not infer title solely from GIS proximity or community assertions.','Land-related assets','Land Use Act 1978 source' FROM regulatory_sources WHERE source_title='Land Use Act 1978' AND NOT EXISTS (SELECT 1 FROM regulatory_rules WHERE rule_code='NG-LAND-001');
INSERT INTO regulatory_rules (source_id,rule_code,rule_domain,rule_text,applicability,evidence_reference) SELECT id,'NG-CORP-001','Corporate','Corporate identity and registration status should be verified against the Corporate Affairs Commission before treating a corporate entity as a verified counterparty.','Companies and institutional counterparties','CAMA 2020 / CAC source' FROM regulatory_sources WHERE source_title='Companies and Allied Matters Act 2020' AND NOT EXISTS (SELECT 1 FROM regulatory_rules WHERE rule_code='NG-CORP-001');
INSERT INTO regulatory_rules (source_id,rule_code,rule_domain,rule_text,applicability,evidence_reference) SELECT id,'NG-DATA-001','Data Protection','Personal-data processing must be evaluated against the Nigeria Data Protection Act 2023 and applicable NDPC requirements; sensitive community and representative information requires controlled access.','All platform workflows processing personal data','NDP Act 2023 / NDPC source' FROM regulatory_sources WHERE source_title='Nigeria Data Protection Act 2023' AND NOT EXISTS (SELECT 1 FROM regulatory_rules WHERE rule_code='NG-DATA-001');
INSERT INTO regulatory_rules (source_id,rule_code,rule_domain,rule_text,applicability,evidence_reference) SELECT id,'NG-ENV-001','Environment','Environmental approval and assessment requirements must be checked before treating a development as environmentally cleared; the platform must not infer environmental clearance from GIS layers alone.','Development and environmentally regulated assets','NESREA EIA Act / regulations repository' FROM regulatory_sources WHERE source_title='Environmental Laws and Regulations / EIA Act' AND NOT EXISTS (SELECT 1 FROM regulatory_rules WHERE rule_code='NG-ENV-001');
INSERT INTO regulatory_rules (source_id,rule_code,rule_domain,rule_text,applicability,evidence_reference) SELECT id,'NG-MIN-001','Mining','Mineral-title and mining-permit status must be verified against the applicable Nigerian mining legal framework and competent ministry records before treating a mineral opportunity as investable.','Mining and mineral assets','Nigerian Minerals and Mining Act 2007 / Ministry source' FROM regulatory_sources WHERE source_title='Nigerian Minerals and Mining Act 2007' AND NOT EXISTS (SELECT 1 FROM regulatory_rules WHERE rule_code='NG-MIN-001');
INSERT INTO regulatory_rules (source_id,rule_code,rule_domain,rule_text,applicability,evidence_reference) SELECT id,'NG-MIN-002','Mining','Mining regulatory workflows include mineral-title applications and community development obligations; the platform should retain documentary evidence and not treat a mineral occurrence as a mineral title.','Mining and mineral assets','Nigerian Minerals and Mining Regulations 2011 / Ministry source' FROM regulatory_sources WHERE source_title='Nigerian Minerals and Mining Regulations 2011' AND NOT EXISTS (SELECT 1 FROM regulatory_rules WHERE rule_code='NG-MIN-002');
INSERT INTO regulatory_framework_versions (jurisdiction_id,version_label,status,rule_count,validated_rule_count,source_count,release_notes) SELECT id,'NG-2026-08-23-v0.1','Draft',6,0,6,'Initial evidence-backed Nigeria seed. All extracted rules remain pending independent validation and legal review; not activated for automated clearance.' FROM continental_jurisdictions WHERE country_code='NG' AND NOT EXISTS (SELECT 1 FROM regulatory_framework_versions WHERE version_label='NG-2026-08-23-v0.1');